/* ==================================== JFSN Filter Container - Complete JavaScript Extracted from main site for standalone use ==================================== */ let galleryData = [];let visibleItems = 20;let currentPage = 0;let isLoading = false;async function loadMetadata(){try{console.log('📁 Loading metadata.json...');const response = await fetch('/metadata.json');if(!response.ok){throw new Error(`HTTP error! status:${response.status}`);}const metadata = await response.json();galleryData = metadata.map((item,index)=>{let artworkNumber = '';if(item.file){const match = item.file.match(/art(\d{4})/);if(match){artworkNumber = match[1];}}const avifPath = artworkNumber ? `artworks/thumbs/art${artworkNumber}.avif`:'data:image/svg+xml;base64,';return{id:index + 1,title:item.title || `Artwork ${artworkNumber || item.file}`,category:item.category || 'Misc',tags:item.keywords || [],keywords:item.keywords || [],image:avifPath,description:item.description || 'No description available',extended_description:item.extended_description || item.description || 'No description available',file:item.file,artworkNumber:artworkNumber,year:2024,featured:false};});console.log(`✅ Loaded ${galleryData.length}artworks from metadata`);console.log('📊 Categories found:',[...new Set(galleryData.map(item => item.category))]);console.log('🎯 Total artworks loaded:',galleryData.length);console.log('🎯 Sample artwork:',galleryData[0]);initLazyLoading();if(galleryData.length !== 1050){console.warn('⚠️ Expected 1050 artworks but got:',galleryData.length);}else{console.log('✅ Correct count:1050 artworks loaded');}return galleryData;}catch(error){console.error('❌ Error loading metadata:',error);galleryData = [];return galleryData;}}let loadMoreState ={filteredData:[],currentPage:0,itemsPerPage:12,loadedItems:0,hasMore:true};const FilterStorage ={saveFilterState:function(filterType,value){try{const currentState = this.getFilterState();currentState[filterType] = value;localStorage.setItem('jfsn_gallery_filters',JSON.stringify(currentState));this.logFilterAction('save',filterType,value);}catch(error){console.warn('Could not save filter state:',error);}},getFilterState:function(){try{const saved = localStorage.getItem('jfsn_gallery_filters');return saved ? JSON.parse(saved):{};}catch(error){console.warn('Could not load filter state:',error);return{};}},clearFilterState:function(){try{localStorage.removeItem('jfsn_gallery_filters');this.logFilterAction('clear','all',null);console.log('Filter preferences cleared');}catch(error){console.warn('Could not clear filter state:',error);}},forceClearAll:function(){try{localStorage.removeItem('jfsn_gallery_filters');localStorage.removeItem('artworkFavorites');console.log('🚨 Force cleared all filter data');}catch(error){console.warn('Could not force clear filter data:',error);}},applyFilterState:function(){try{const savedState = this.getFilterState();if(savedState.category){const targetChip = document.querySelector(`.filter-chip[data-category="${savedState.category}"]`);if(targetChip){setActiveFilterChip(targetChip);showCategoryContentBlock(savedState.category);filterGalleryVirtual('',savedState.category);}}}catch(error){console.warn('Could not apply saved filter state:',error);}},logFilterAction:function(action,filterType,value){console.log(`Filter ${action}:`,{filterType,value,timestamp:new Date().toISOString()});}};function createFilterButtons(){const filterSection = document.getElementById('filterSection');if(!filterSection || !galleryData || galleryData.length === 0){console.warn('Filter section not found or gallery data not loaded');return;}const existingMobileChips = document.querySelector('.mobile-filter-chips');if(existingMobileChips){existingMobileChips.remove();console.log('Removed existing mobile filter bar');}const filterChips = filterSection.querySelectorAll('.filter-chip,.filter-label-chip');filterChips.forEach(chip => chip.remove());document.querySelectorAll('.filter-chip').forEach(chip =>{if(chip.textContent.includes('1050')){chip.remove();console.log('🚨 Force removed All 1050 chip from createFilterButtons');}});const labelChip = document.createElement('div');labelChip.className = 'filter-chip filter-label-chip';labelChip.innerHTML = `<span class="filter-text">PICK A FILTER ></span>`;filterSection.appendChild(labelChip);const categoryStats ={};galleryData.forEach(item =>{const category = item.category || 'misc';categoryStats[category] =(categoryStats[category] || 0)+ 1;});console.log('🎯 Categories being created:',Object.keys(categoryStats));const sortedCategories = Object.entries(categoryStats).sort((a,b)=>{if(b[1] !== a[1])return b[1] - a[1];return a[0].localeCompare(b[0]);});const allButton = document.createElement('button');allButton.className = 'filter-chip';allButton.setAttribute('data-category','all');allButton.innerHTML = ` <span class="filter-text">All</span> <span class="filter-count">${galleryData.length}</span> `;filterSection.appendChild(allButton);let newCategoryButton = null;const regularCategories = [];sortedCategories.forEach(([category,count])=>{if(category.toLowerCase()=== 'new'){newCategoryButton ={category,count};}else{regularCategories.push([category,count]);}});if(newCategoryButton){const button = document.createElement('button');button.className = 'filter-chip';button.setAttribute('data-category',newCategoryButton.category);const displayName = newCategoryButton.category.split(' ').map(word => word.charAt(0).toUpperCase()+ word.slice(1)).join(' ');button.innerHTML = ` <span class="filter-text">${displayName}</span> <span class="filter-count">${newCategoryButton.count}</span> `;filterSection.appendChild(button);}regularCategories.forEach(([category,count])=>{const button = document.createElement('button');button.className = 'filter-chip';button.setAttribute('data-category',category);const displayName = category.split(' ').map(word => word.charAt(0).toUpperCase()+ word.slice(1)).join(' ');button.innerHTML = ` <span class="filter-text">${displayName}</span> <span class="filter-count">${count}</span> `;filterSection.appendChild(button);});const specialFilters = [{category:'horizontal',displayName:'Horizontal',icon:'fa-rectangle-wide'},{category:'vertical',displayName:'Vertical',icon:'fa-rectangle-tall'},{category:'square',displayName:'Square',icon:'fa-square'},{category:'favorites',displayName:'Favorites',icon:'fa-heart'}];specialFilters.forEach(filter =>{const count = getSpecialFilterCount(filter.category);const button = document.createElement('button');button.className = 'filter-chip';button.setAttribute('data-category',filter.category);button.innerHTML = ` <i class="fas ${filter.icon}me-1"></i> <span class="filter-text">${filter.displayName}</span> <span class="filter-count">${count}</span> `;filterSection.appendChild(button);});console.log('✅ Filter buttons created:',sortedCategories.length + 1 + 4,'total buttons(including special filters)');const createdChips = filterSection.querySelectorAll('.filter-chip');console.log('🎯 Actually created chips:',Array.from(createdChips).map(chip => chip.textContent.trim()));}function getSpecialFilterCount(category){if(!galleryData || galleryData.length === 0)return 0;switch(category){case 'horizontal':return galleryData.filter(item =>{return Math.floor(galleryData.length * 0.4);}).length;case 'vertical':return Math.floor(galleryData.length * 0.35);case 'square':return Math.floor(galleryData.length * 0.25);case 'favorites':const favorites = JSON.parse(localStorage.getItem('artworkFavorites')|| '[]');return favorites.length;default:return 0;}}function checkOrientationMatch(item,category){const orientationCache = JSON.parse(localStorage.getItem('artworkOrientations')|| '{}');const cachedOrientation = orientationCache[item.id];if(cachedOrientation){switch(category){case 'horizontal':return cachedOrientation === 'horizontal';case 'vertical':return cachedOrientation === 'vertical';case 'square':return cachedOrientation === 'square';default:return false;}}return true;}function initFilters(){const filterChips = document.querySelector('.filter-chips');if(!filterChips){console.warn('Filter chips container not found');return;}filterChips.addEventListener('click',(e)=>{e.preventDefault();const button = e.target.closest('.filter-chip');if(!button)return;button.classList.add('loading');setActiveFilterChip(button);setTimeout(()=>{setActiveFilterChip(button);},50);centerActiveChip(button,filterChips);const category = button.getAttribute('data-category');console.log('🎯 Filter chip clicked:',category);showCategoryContentBlock(category);filterGalleryVirtual('',category);FilterStorage.saveFilterState('category',category);setTimeout(()=>{button.classList.remove('loading');},300);});filterChips.addEventListener('keydown',(e)=>{const activeChip = filterChips.querySelector('.filter-chip.active');if(!activeChip)return;let nextChip = null;if(e.key === 'ArrowRight'){nextChip = activeChip.nextElementSibling;if(!nextChip)nextChip = filterChips.firstElementChild;}else if(e.key === 'ArrowLeft'){nextChip = activeChip.previousElementSibling;if(!nextChip)nextChip = filterChips.lastElementChild;}else if(e.key === 'Enter' || e.key === ' '){e.preventDefault();activeChip.click();return;}if(nextChip){e.preventDefault();nextChip.focus();nextChip.click();}});initScrollIndicators(filterChips);}function centerActiveChip(chip,container){const containerRect = container.getBoundingClientRect();const chipRect = chip.getBoundingClientRect();const containerCenter = containerRect.left + containerRect.width / 2;const chipCenter = chipRect.left + chipRect.width / 2;const offset = chipCenter - containerCenter;container.scrollBy({left:offset,behavior:'smooth'});}function initScrollIndicators(container){const updateScrollIndicators =()=>{const{scrollLeft,scrollWidth,clientWidth}= container;const canScrollLeft = scrollLeft > 0;const canScrollRight = scrollLeft < scrollWidth - clientWidth - 1;container.style.setProperty('--fade-left',canScrollLeft ? '1':'0');container.style.setProperty('--fade-right',canScrollRight ? '1':'0');container.classList.toggle('can-scroll-left',canScrollLeft);container.classList.toggle('can-scroll-right',canScrollRight);};updateScrollIndicators();container.addEventListener('scroll',updateScrollIndicators,{passive:true});window.addEventListener('resize',updateScrollIndicators,{passive:true});}function initMobileFilterDrawer(){if(window.innerWidth > 768){const existingMobileChips = document.querySelector('.mobile-filter-chips');if(existingMobileChips){existingMobileChips.remove();}const regularFilter = document.querySelector('.filter-container');if(regularFilter){regularFilter.style.display = 'block';}return;}const regularFilter = document.querySelector('.filter-container');if(regularFilter){regularFilter.style.display = 'none';}const existingMobileChips = document.querySelector('.mobile-filter-chips');if(existingMobileChips){existingMobileChips.remove();}const controlsContainer = document.querySelector('.controls-container');if(!controlsContainer)return;const mobileChipsContainer = document.createElement('div');mobileChipsContainer.className = 'mobile-filter-chips';const heroSection = document.querySelector('.immersive-hero')|| document.querySelector('.hero-section')|| document.querySelector('.hero')|| document.querySelector('header');if(heroSection && heroSection.nextElementSibling){heroSection.parentNode.insertBefore(mobileChipsContainer,heroSection.nextElementSibling);}else{document.body.insertBefore(mobileChipsContainer,document.body.firstChild);}populateMobileFilters();}function populateMobileFilters(){const mobileChipsContainer = document.querySelector('.mobile-filter-chips');console.log('populateMobileFilters called:',{mobileChipsContainer,isMobile:window.innerWidth <= 768,width:window.innerWidth});if(!mobileChipsContainer){console.error('Mobile chips container not found!');return;}if(!galleryData || galleryData.length === 0){console.error('Gallery data not loaded yet!');return;}mobileChipsContainer.innerHTML = '';document.querySelectorAll('.filter-chip').forEach(chip =>{if(chip.textContent.includes('1050')){chip.remove();console.log('🚨 Force removed All 1050 chip from mobile filters');}});const filterContainer = document.createElement('div');filterContainer.className = 'filter-container';filterContainer.style.cssText = ` display:flex;align-items:center;width:100%;padding:0.125rem 0.75rem;min-height:3rem;`;const filterChips = document.createElement('div');filterChips.className = 'filter-chips';const mobileLabelChip = document.createElement('div');mobileLabelChip.className = 'filter-chip filter-label-chip';mobileLabelChip.innerHTML = `<span class="filter-text">PICK A FILTER ></span>`;filterChips.appendChild(mobileLabelChip);filterChips.style.cssText = ` display:flex;gap:0.375rem;align-items:center;overflow-x:auto;overflow-y:visible;scrollbar-width:none;-ms-overflow-style:none;padding:0.125rem 0.75rem;white-space:nowrap;position:relative;z-index:1;scroll-behavior:smooth;scroll-snap-type:x mandatory;transition:all 0.3s ease;flex:1;min-height:2.5rem;`;const categoryStats ={};galleryData.forEach(item =>{const category = item.category || 'misc';categoryStats[category] =(categoryStats[category] || 0)+ 1;});const sortedCategories = Object.entries(categoryStats).sort((a,b)=>{if(b[1] !== a[1])return b[1] - a[1];return a[0].localeCompare(b[0]);});const allButton = document.createElement('button');allButton.className = 'filter-chip';allButton.setAttribute('data-category','all');allButton.innerHTML = ` <span class="filter-text">All</span> <span class="filter-count">${galleryData.length}</span> `;filterChips.appendChild(allButton);let newCategoryButton = null;const regularCategories = [];sortedCategories.forEach(([category,count])=>{if(category.toLowerCase()=== 'new'){newCategoryButton ={category,count};}else{regularCategories.push([category,count]);}});if(newCategoryButton){const button = document.createElement('button');button.className = 'filter-chip';button.setAttribute('data-category',newCategoryButton.category);const displayName = newCategoryButton.category.split(' ').map(word => word.charAt(0).toUpperCase()+ word.slice(1)).join(' ');button.innerHTML = ` <span class="filter-text">${displayName}</span> <span class="filter-count">${newCategoryButton.count}</span> `;filterChips.appendChild(button);}regularCategories.forEach(([category,count])=>{const button = document.createElement('button');button.className = 'filter-chip';button.setAttribute('data-category',category);const displayName = category.split(' ').map(word => word.charAt(0).toUpperCase()+ word.slice(1)).join(' ');button.innerHTML = ` <span class="filter-text">${displayName}</span> <span class="filter-count">${count}</span> `;filterChips.appendChild(button);});const specialFilters = [{category:'horizontal',displayName:'Horizontal',icon:'fa-rectangle-wide'},{category:'vertical',displayName:'Vertical',icon:'fa-rectangle-tall'},{category:'square',displayName:'Square',icon:'fa-square'},{category:'favorites',displayName:'Favorites',icon:'fa-heart'}];specialFilters.forEach(filter =>{const count = getSpecialFilterCount(filter.category);const button = document.createElement('button');button.className = 'filter-chip';button.setAttribute('data-category',filter.category);button.innerHTML = ` <i class="fas ${filter.icon}me-1"></i> <span class="filter-text">${filter.displayName}</span> <span class="filter-count">${count}</span> `;filterChips.appendChild(button);});filterContainer.appendChild(filterChips);mobileChipsContainer.appendChild(filterContainer);console.log('🎯 Attaching mobile filter click handler to:',filterChips);filterChips.addEventListener('click',(e)=>{console.log('🎯 Mobile filter click event triggered!',e.target);e.preventDefault();const chip = e.target.closest('.filter-chip');console.log('🎯 Closest filter chip found:',chip);if(!chip)return;if(navigator.vibrate){navigator.vibrate(30);}chip.classList.add('loading');setActiveFilterChip(chip);centerActiveChip(chip,filterChips);const category = chip.getAttribute('data-category');console.log('🎯 Mobile filter clicked:',{category,chipText:chip.textContent.trim()});showCategoryContentBlock(category);filterGalleryVirtual('',category);FilterStorage.saveFilterState('category',category);setTimeout(()=>{chip.classList.remove('loading');},300);});let startX = 0;let startY = 0;let isScrolling = false;filterChips.addEventListener('touchstart',(e)=>{startX = e.touches[0].clientX;startY = e.touches[0].clientY;isScrolling = false;},{passive:true});filterChips.addEventListener('touchmove',(e)=>{const deltaX = Math.abs(e.touches[0].clientX - startX);const deltaY = Math.abs(e.touches[0].clientY - startY);if(deltaX > deltaY && deltaX > 10){isScrolling = true;}},{passive:true});filterChips.addEventListener('touchend',(e)=>{if(!isScrolling){const button = e.target.closest('.filter-chip');if(button){button.click();}}startX = 0;startY = 0;isScrolling = false;},{passive:true});filterChips.addEventListener('keydown',(e)=>{const activeChip = filterChips.querySelector('.filter-chip.active');if(!activeChip)return;let nextChip = null;if(e.key === 'ArrowRight'){nextChip = activeChip.nextElementSibling;if(!nextChip)nextChip = filterChips.firstElementChild;}else if(e.key === 'ArrowLeft'){nextChip = activeChip.previousElementSibling;if(!nextChip)nextChip = filterChips.lastElementChild;}else if(e.key === 'Enter' || e.key === ' '){e.preventDefault();activeChip.click();return;}if(nextChip){e.preventDefault();nextChip.focus();nextChip.click();}});initScrollIndicators(filterChips);}function showCategoryContentBlock(category){console.log('Showing category content for:',category);const curatedBlock = document.getElementById('curatedCollectionBlock');if(curatedBlock){if(category === 'all'){curatedBlock.style.display = 'block';console.log('✅ Showing curated collection block');}else{curatedBlock.style.display = 'none';console.log('✅ Hiding curated collection block');}}const event = new CustomEvent('filterChanged',{detail:{category}});document.dispatchEvent(event);}function filterGallery(query = '',category = 'all'){console.log('🔍 Filtering gallery:',{query,category});if(!galleryData || galleryData.length === 0){console.warn('Gallery data not loaded');return;}const filteredData = galleryData.filter(item =>{const matchesQuery = !query || item.title.toLowerCase().includes(query.toLowerCase())||(item.keywords && item.keywords.some(keyword => keyword.toLowerCase().includes(query.toLowerCase())));let matchesCategory = false;if(category === 'all'){matchesCategory = true;}else if(category === 'featured'){const itemId = item.id || '';matchesCategory = itemId === '1009' || itemId === '1010' || item.title.toLowerCase().includes('featured artwork 1009')|| item.title.toLowerCase().includes('featured artwork 1010');}else{const itemCategoryLower = item.category.toLowerCase();const filterCategoryLower = category.toLowerCase();matchesCategory = itemCategoryLower === filterCategoryLower;}return matchesQuery && matchesCategory;});console.log('📊 Filtered results:',filteredData.length,'items');const event = new CustomEvent('galleryFiltered',{detail:{filteredData,query,category}});document.dispatchEvent(event);return filteredData;}function initLazyLoading(){if('IntersectionObserver' in window){const imageObserver = new IntersectionObserver((entries,observer)=>{entries.forEach(entry =>{if(entry.isIntersecting){const img = entry.target;if(img.dataset.src){img.src = img.dataset.src;img.removeAttribute('data-src');img.loading = 'lazy';observer.unobserve(img);}}});},{rootMargin:'100px 0px',threshold:0.01});document.querySelectorAll('img[data-src]').forEach(img =>{imageObserver.observe(img);});}}function loadInitialItems(){const initialItems = galleryData.slice(0,visibleItems);console.log(`📱 Loading initial ${visibleItems}items for mobile performance`);return initialItems;}function loadMoreItems(){if(isLoading)return;isLoading = true;const startIndex = currentPage * visibleItems;const endIndex = startIndex + visibleItems;const newItems = galleryData.slice(startIndex,endIndex);if(newItems.length > 0){currentPage++;console.log(`📱 Loading more items:${startIndex}-${endIndex}`);return newItems;}isLoading = false;return [];}function filterGalleryVirtual(query = '',category = 'all'){console.log('🔍 Load more filtering:',{query,category});loadMoreState.filteredData = galleryData.filter(item =>{const matchesQuery = !query || item.title.toLowerCase().includes(query.toLowerCase())||(item.keywords && item.keywords.some(keyword => keyword.toLowerCase().includes(query.toLowerCase())));let matchesCategory = false;if(category === 'all'){matchesCategory = true;}else if(category === 'featured'){const itemId = item.id || '';matchesCategory = itemId === '1009' || itemId === '1010' || item.title.toLowerCase().includes('featured artwork 1009')|| item.title.toLowerCase().includes('featured artwork 1010');}else if(category === 'favorites'){const favorites = JSON.parse(localStorage.getItem('artworkFavorites')|| '[]');matchesCategory = favorites.includes(item.id);}else if(category === 'horizontal' || category === 'vertical' || category === 'square'){matchesCategory = checkOrientationMatch(item,category);}else{const itemCategoryLower = item.category.toLowerCase();const filterCategoryLower = category.toLowerCase();matchesCategory = itemCategoryLower === filterCategoryLower;}return matchesQuery && matchesCategory;});console.log('📊 Filtered results:',loadMoreState.filteredData.length,'items');loadMoreState.currentPage = 0;loadMoreState.loadedItems = 0;loadMoreState.hasMore = loadMoreState.filteredData.length > 0;const event = new CustomEvent('galleryFilteredVirtual',{detail:{filteredData:loadMoreState.filteredData,query,category,loadMoreState:{...loadMoreState}}});document.dispatchEvent(event);return loadMoreState.filteredData;}function initFilterPersistence(){setTimeout(()=>{FilterStorage.applyFilterState();},100);}function isMobileDevice(){return window.innerWidth <= 768 || /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);}function setActiveFilterChip(targetChip){console.log('🎯 Setting active chip:',targetChip ? targetChip.textContent.trim():'none');document.querySelectorAll('.filter-chip').forEach(chip =>{chip.classList.remove('active');});if(targetChip){targetChip.classList.add('active');console.log('✅ Set active:',targetChip.textContent.trim());}const activeChips = document.querySelectorAll('.filter-chip.active');if(activeChips.length > 1){console.warn('🚨 Multiple chips still active after setActiveFilterChip:',activeChips.length);activeChips.forEach(chip =>{if(chip !== targetChip){chip.classList.remove('active');}});}}function ensureSingleActiveChip(){const activeChips = document.querySelectorAll('.filter-chip.active');if(activeChips.length > 1){console.log('🚨 Multiple active chips detected,fixing...',activeChips.length);for(let i = 1;i < activeChips.length;i++){activeChips[i].classList.remove('active');}}else if(activeChips.length === 0){console.log('🚨 No active chips detected - this is normal on initial load');}}document.addEventListener('DOMContentLoaded',function(){console.log('🎯 Filter system initializing...');FilterStorage.forceClearAll();initFilterPersistence();async function initializeFilterSystem(){try{await loadMetadata();if(galleryData && galleryData.length > 0){createFilterButtons();initFilters();if(window.innerWidth <= 768){initMobileFilterDrawer();}showCategoryContentBlock('all');setTimeout(()=>{window.scrollTo(0,0);},100);console.log('✅ Filter system initialized with',galleryData.length,'items');setInterval(ensureSingleActiveChip,200);setTimeout(ensureSingleActiveChip,100);setTimeout(ensureSingleActiveChip,500);setTimeout(ensureSingleActiveChip,1000);}else{console.warn('⚠️ No gallery data loaded');}}catch(error){console.error('❌ Failed to initialize filter system:',error);}}initializeFilterSystem();});window.addEventListener('resize',function(){if(window.innerWidth <= 768){initMobileFilterDrawer();}else{const mobileChips = document.querySelector('.mobile-filter-chips');if(mobileChips){mobileChips.remove();}}});if(typeof module !== 'undefined' && module.exports){module.exports ={FilterStorage,createFilterButtons,initFilters,filterGallery,filterGalleryVirtual,initFilterPersistence};}